/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Data contract class for the order shipment bundling reporting job.
/// </summary>
[DataContract]
class METOrderShipmentBundlingReportingJobContract extends METSysOperationTaskDataContract
{
    MetLoadId loadId;
    MetShipmentId shipmentId;
    guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Parm method for the load number
/// </summary>
/// <param name = "_loadId">the load number</param>
/// <returns>the load number</returns>
[DataMemberAttribute('loadId')]
public MetLoadId parmLoadId(MetLoadId _loadId = loadId)
{
    loadId = _loadId;
    return loadId;
}

/// <summary>
/// Parm method for the shipment Id.
/// </summary>
/// <param name = "_shipmentId">Shipment Id.</param>
/// <returns>Shipment Id.</returns>
[DataMemberAttribute('shipmentId')]
public MetShipmentId parmShipmentId(MetShipmentId _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;
    return shipmentId;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}
